#include "bus.h"
#define MANAGER_PATH "/org/freedesktop/NetworkManager"
#define DEVICE NM ".Device"
#define WIRELESS DEVICE ".Wireless"
#define ACTIVE NM ".Connection.Active"
struct device {char *path,*active,*uuid;int mode,state,active_state;bool managed,autoconnect;};
static char *scalar(char *s){if(!s)return NULL;struct json j;char *v=NULL;if(jparse(&j,s))v=jtext(&j,jidx(&j,jget(&j,0,"data"),0));free(j.v);free(s);return v;}
static char *nmcall(const char *path,const char *iface,const char *method,const char *sig,const char *v1,const char *v2,const char *v3){const char *a[]={"call",NM,path,iface,method,sig,v1,v2,v3,NULL};return bus_run(false,a);}
static char *all(const char *path,const char *iface){return nmcall(path,PROPS,"GetAll","s",iface,NULL,NULL);}
static int prop(struct json *j,const char *key){return jget(j,jget(j,jidx(j,jget(j,0,"data"),0),key),"data");}
static void release_device(struct device *d){free(d->path);free(d->active);free(d->uuid);memset(d,0,sizeof(*d));}
static int device(struct device *d){memset(d,0,sizeof(*d));d->path=scalar(nmcall(MANAGER_PATH,NM,"GetDeviceByIpIface","s","wlan0",NULL,NULL));if(!d->path)return -1;
    char *s=all(d->path,DEVICE);if(!s)goto fail;struct json j;bool valid=jparse(&j,s);if(!valid){free(j.v);free(s);goto fail;}int64_t n;if(!jlong(&j,prop(&j,"State"),&n)){free(j.v);free(s);goto fail;}d->state=n;d->managed=jbool(&j,prop(&j,"Managed"))==1;d->autoconnect=jbool(&j,prop(&j,"Autoconnect"))!=0;d->active=jtext(&j,prop(&j,"ActiveConnection"));free(j.v);free(s);
    s=all(d->path,WIRELESS);if(!s)goto fail;if(!jparse(&j,s)||!jlong(&j,prop(&j,"Mode"),&n)){free(j.v);free(s);goto fail;}d->mode=n;free(j.v);free(s);
    if(d->active&&strcmp(d->active,"/")){s=all(d->active,ACTIVE);if(s){if(jparse(&j,s)){d->uuid=jtext(&j,prop(&j,"Uuid"));if(jlong(&j,prop(&j,"State"),&n))d->active_state=n;}free(j.v);free(s);}}
    return 0;
 fail:release_device(d);return -1;
}
static int radio(void){return bus_bool(false,NM,MANAGER_PATH,NM,"WirelessEnabled");}
static int auto_connect(bool enabled){struct device d;if(device(&d))return -1;int r=bus_set(false,NM,d.path,DEVICE,"Autoconnect",enabled);release_device(&d);return r;}
static int show_status(void){struct device d;int r=radio();if(r<0||device(&d))return json_error("Wi-Fi unavailable");bool active=d.active&&strcmp(d.active,"/")&&d.active_state;const char *mode=!r?"off":d.mode==3&&active?"ap":(d.mode==2&&active)||d.autoconnect?"sta":"idle";printf("{\"ok\":true,\"radio\":%s,\"mode\":\"%s\",\"hardware_enabled\":%s}\n",truth(r),mode,truth(bus_bool(false,NM,MANAGER_PATH,NM,"WirelessHardwareEnabled")));release_device(&d);return 0;}
static int idle(const char *state,int new_radio){if(auto_connect(false))return -1;struct device d;if(device(&d))return -1;bool active=d.active&&strcmp(d.active,"/")&&d.active_state;
    if(active||(d.state>=40&&d.state<=110)){char *s=nmcall(d.path,DEVICE,"Disconnect",NULL,NULL,NULL,NULL);if(!s){release_device(&d);return -1;}free(s);}release_device(&d);int64_t end=mono_ms()+15000;
    for(;;){if(device(&d))return -1;bool ready=(!d.active||!strcmp(d.active,"/")||!d.active_state)&&(d.state<40||d.state>110);release_device(&d);if(ready)break;if(mono_ms()>=end)return -1;usleep(150000);}
    if(new_radio>=0&&bus_set(false,NM,MANAGER_PATH,NM,"WirelessEnabled",new_radio))return -1;unlink(state);return 0;
}
static int save_state(const char *path,bool radio,const char *uuid,const char *phase){char *tmp=NULL;asprintf(&tmp,"%s.tmp.%ld",path,(long)getpid());int fd=open(tmp,O_WRONLY|O_CREAT|O_EXCL|O_NOFOLLOW|O_CLOEXEC,0600);if(fd<0){free(tmp);return -1;}FILE *f=fdopen(fd,"w");fprintf(f,"{\"radio_enabled\":%s,\"previous_uuid\":",truth(radio));json_string(f,uuid?uuid:"");fputs(",\"phase\":",f);json_string(f,phase);fputs("}\n",f);bool bad=fflush(f)||fsync(fd);if(fclose(f))bad=true;if(!bad&&rename(tmp,path))bad=true;if(bad)unlink(tmp);free(tmp);return bad?-1:0;}
static char *read_state(const char *path){struct stat st;if(lstat(path,&st)){return NULL;}if(!S_ISREG(st.st_mode)||st.st_uid!=getuid())return NULL;char *s=read_text(path);if(!s)return NULL;struct json j;bool ok=jparse(&j,s)&&j.v[0].type=='{';free(j.v);if(!ok){free(s);return NULL;}return s;}
static int prepare(const char *state){if(bus_bool(false,NM,MANAGER_PATH,NM,"NetworkingEnabled")!=1)return -1;struct device d;if(device(&d))return -1;if(d.mode==3){release_device(&d);return -1;}int on=radio();if(on<0){release_device(&d);return -1;}
    char *previous=d.mode==2&&d.uuid?strdup(d.uuid):strdup("");release_device(&d);char *old=read_state(state);if(old){struct json j;if(jparse(&j,old)&&jeq(&j,jget(&j,0,"phase"),"preparing")){int v=jbool(&j,jget(&j,0,"radio_enabled"));if(v>=0)on=v;char *saved=jtext(&j,jget(&j,0,"previous_uuid"));if(saved){free(previous);previous=saved;}}free(j.v);free(old);}
    int result=-1;if(save_state(state,on,previous,"preparing")||auto_connect(false))goto done;if(radio()==0&&bus_set(false,NM,MANAGER_PATH,NM,"WirelessEnabled",true))goto done;int64_t end=mono_ms()+15000;
    while(mono_ms()<end){if(radio()!=1||device(&d))goto done;bool ready=d.managed&&d.state>=30&&d.state<=100;if(ready&&on&&!*previous&&d.mode==2&&d.uuid){free(previous);previous=strdup(d.uuid);if(save_state(state,on,previous,"preparing")){release_device(&d);goto done;}}release_device(&d);if(ready){puts("{\"ok\":true,\"ready\":true}");result=0;break;}usleep(150000);}
 done:free(previous);return result;
}
static int verify(const char *state){int64_t end=mono_ms()+40000;while(mono_ms()<end){if(radio()!=1)return -1;struct device d;if(device(&d))return -1;bool failed=d.state==120||d.active_state==4,ready=d.mode==3&&d.state==100&&d.active_state==2;release_device(&d);if(failed)return -1;if(ready){char *s=read_state(state);if(s){struct json j;if(jparse(&j,s)){char *uuid=jtext(&j,jget(&j,0,"previous_uuid"));int on=jbool(&j,jget(&j,0,"radio_enabled"));if(save_state(state,on==1,uuid,"active")){free(uuid);free(j.v);free(s);return -1;}free(uuid);}free(j.v);free(s);}puts("{\"ok\":true,\"active\":true}");return 0;}usleep(200000);}return -1;}
static int create(void){struct device d;if(device(&d))return -1;char *list=nmcall(MANAGER_PATH"/Settings",NM".Settings","ListConnections",NULL,NULL,NULL,NULL);if(!list){release_device(&d);return -1;}struct json j;char *chosen=NULL;int count=0;bool chosen_active=false;if(jparse(&j,list)){int paths=jidx(&j,jget(&j,0,"data"),0);for(int n=0;;n++){int t=jidx(&j,paths,n);if(t<0)break;char *path=jtext(&j,t);if(!path)continue;char *settings=nmcall(path,NM".Settings.Connection","GetSettings",NULL,NULL,NULL,NULL);if(settings){struct json s;if(jparse(&s,settings)){int root=jidx(&s,jget(&s,0,"data"),0),c=jget(&s,root,"connection"),w=jget(&s,root,"802-11-wireless");int type=jget(&s,jget(&s,c,"type"),"data"),mode=jget(&s,jget(&s,w,"mode"),"data"),iface=jget(&s,jget(&s,c,"interface-name"),"data");if(jeq(&s,type,"802-11-wireless")&&jeq(&s,mode,"ap")&&(iface<0||jeq(&s,iface,"")||jeq(&s,iface,"wlan0"))){count++;char *uuid=jtext(&s,jget(&s,jget(&s,c,"uuid"),"data"));if(count==1&&!chosen_active){free(chosen);chosen=strdup(path);}if(uuid&&d.uuid&&!strcmp(uuid,d.uuid)){free(chosen);chosen=strdup(path);chosen_active=true;}free(uuid);}}free(s.v);free(settings);}free(path);}}
    free(j.v);free(list);int result=-1;if(chosen&&(count==1||chosen_active)){char *active=scalar(nmcall(MANAGER_PATH,NM,"ActivateConnection","ooo",chosen,d.path,"/"));if(active){fputs("{\"ok\":true,\"active_path\":",stdout);json_string(stdout,active);puts("}");free(active);result=0;}}free(chosen);release_device(&d);return result;
}
int main(int argc,char **argv){if(argc!=2)return json_error("Invalid hotspot operation");const char *action=argv[1];const char *allowed[]={"prepare","create","verify","restore","rollback","status","idle","sta","radio-on","radio-off"};bool valid=false;for(size_t i=0;i<sizeof(allowed)/sizeof(*allowed);i++)if(!strcmp(action,allowed[i]))valid=true;if(!valid)return json_error("Invalid hotspot operation");if(!strcmp(action,"status"))return show_status();
    const char *runtime=getenv("XDG_RUNTIME_DIR");struct stat st;if(!runtime||stat(runtime,&st)||!S_ISDIR(st.st_mode)||st.st_uid!=getuid())return json_error("Invalid runtime directory");char *state=path_join(runtime,"w202-hotspot-switch.json"),*lock=path_join(runtime,"w202-hotspot-switch.lock");int fd=open(lock,O_RDWR|O_CREAT|O_NOFOLLOW|O_CLOEXEC,0600);free(lock);if(fd<0||flock(fd,LOCK_EX|LOCK_NB)){free(state);if(fd>=0)close(fd);return json_error("A hotspot operation is already running");}
    int result;if(!strcmp(action,"prepare"))result=prepare(state);else if(!strcmp(action,"verify"))result=verify(state);else if(!strcmp(action,"create"))result=create();else {int on=!strcmp(action,"sta")||!strcmp(action,"radio-on")?1:!strcmp(action,"radio-off")?0:-1;result=idle(state,on);if(!result&&!strcmp(action,"sta"))result=auto_connect(true);if(!result)result=show_status();}close(fd);free(state);return result?json_error("Wi-Fi operation failed; check saved AP connections and device state"):0;
}
